package gt.com.ro.devumgapp.notificacion;
import java.util.Map; import gt.com.ro.devumgapp.core.dto.PageResponse; import retrofit2.Call; import retrofit2.http.*;
public interface NotificationApi { @GET("api/notificaciones/me") Call<PageResponse<NotificationModels.Item>> list(@Query("page")int page,@Query("size")int size); @GET("api/notificaciones/me/count") Call<NotificationModels.Count> count(); @GET("api/notificaciones/me/{id}") Call<NotificationModels.Item> get(@Path("id")long id); @PATCH("api/notificaciones/me/{id}/leida") Call<NotificationModels.Item> read(@Path("id")long id); @PATCH("api/notificaciones/me/leidas") Call<Map<String,Integer>> readAll(); @DELETE("api/notificaciones/me/{id}") Call<Void> delete(@Path("id")long id); @DELETE("api/notificaciones/me") Call<Map<String,Integer>> clear(); @POST("api/notificaciones/me/dispositivos") Call<Void> register(@Body NotificationModels.Device d); @DELETE("api/notificaciones/me/dispositivos") Call<Void> unregister(@Query("token")String token); }
